// Purpose: Summarise a flow's node status messages into one flow health value.
// Input:   msg from a Node-RED Status node, with msg.status and msg.source.
// Output:  msg.payload = { timestamp, status }
// Notes:   Health is also written to global.sysStatus.Flow[flowName].isHealthy.

const nodeStatuses = context.get("nodeStatuses") || {};
const now = Date.now();
const flowName = env.get("FLOW_NAME");

const sourceId = msg.status?.source?.id;
const statusFill = (msg.status?.fill || "").toLowerCase();

nodeStatuses[sourceId] = {
    fill: statusFill,
    lastUpdate: now,
};

context.set("nodeStatuses", nodeStatuses);

const hasFault = Object.values(nodeStatuses).some(
    (nodeStatus) => nodeStatus.fill === "red",
);
const summaryIsHealthy = !hasFault;
const summary = summaryIsHealthy ? "healthy" : "unhealthy";

const sysStatus = global.get("sysStatus") || {};
sysStatus.Flow ??= {};
sysStatus.Flow[flowName] ??= {};
sysStatus.Flow[flowName].isHealthy = summaryIsHealthy;
sysStatus.Flow[flowName].lastUpdate = now;
global.set("sysStatus", sysStatus);

msg.payload = {
    timestamp: now,
    status: summary,
};

msg.flowName = flowName;

return msg;

// Function to convert a timestamp to local time in dd/mm/yyyy, hh:mm:ss AM/PM format
const convertToLocalTime = (timestamp) => {
  const date = new Date(timestamp * 1000); // Convert from seconds to milliseconds

  // Get the raw date values
  let day = date.getDate().toString().padStart(2, '0');
  let month = (date.getMonth() + 1).toString().padStart(2, '0');
  let year = date.getFullYear();

  let hours = date.getHours();
  let minutes = date.getMinutes().toString().padStart(2, '0');
  let seconds = date.getSeconds().toString().padStart(2, '0');

  // Determine AM/PM and adjust the hour if necessary
  let period = 'AM';
  if (hours >= 12) {
    period = 'PM';
    if (hours > 12) {
      hours -= 12; // Convert to 12-hour format
    }
  } else if (hours === 0) {
    hours = 12; // Handle midnight (00:xx)
  }

  // Format the final string
  let formattedDate = `${day}/${month}/${year}, ${hours}:${minutes}:${seconds} ${period}`;
  return formattedDate;
};

const containers = msg.payload;
let currentTime = Date.now();

// Function to capitalize the first letter of each word
const capitalizeFirstWord = (str) => {
  return str && str.length > 0
    ? str.charAt(0).toUpperCase() + str.slice(1).toLowerCase()
    : str;
};

// Function to check if a timestamp is valid (not negative, zero, null, or undefined)
const isValidTimestamp = (timestamp) => {
  return timestamp && timestamp >= 0;
};

// Filter out containers with the excluded name
const filteredContainers = containers.filter(container =>
  !(container.Names && container.Names.includes("core-common-config-bootstrapper"))
);

// Extract the required fields for each remaining container
const extractedFields = filteredContainers.map(container => ({
  Name: container.Names ? container.Names.map(name => capitalizeFirstWord(name)).join(", ") : "Unknown", // Capitalize first letter of each name
  StartedAt: isValidTimestamp(container.StartedAt) ? convertToLocalTime(container.StartedAt) : "N/A", // Convert Unix timestamp to local time
  State: container.State,
  Status: container.Status,
  Exited: container.Exited ? capitalizeFirstWord(container.Exited.toString()) : "N/A", // Capitalize Exited if available
  ExitCode: container.ExitCode,
  // Only set ExitedAt if ExitCode is non-zero (true)
  ExitedAt: container.ExitCode !== 0 && isValidTimestamp(container.ExitedAt) ? convertToLocalTime(container.ExitedAt) : "N/A",
  LastUpdated: currentTime
}));

// Set the result to msg.payload
msg.payload = extractedFields;

// Store the extracted fields in global container status
global.set("containerStatus", extractedFields) || [];

return msg;

/**
 * Parse WS readings (if present), then derive slot pointer from LocationName.
 * - Supports WS "readings[]" format and already-flattened inject payloads.
 * - Sets: msg.locationName, msg.slot, msg.isEnabledLocation, msg.endpointKey
 */

// ---------- Parse readings[] if present ----------
if (msg.payload?.readings?.length > 0) {
  const payload = {};

  msg.payload.readings.forEach(item => {
    payload[item.resourceName] =
      item.valueType === "String" ? item.value : Number(item.value);
  });

  msg.payload = payload;
} else {
  // If payload is already a plain object, allow it through (inject/testing)
  if (!(msg.payload && typeof msg.payload === "object" && !Array.isArray(msg.payload))) {
    node.warn("Payload is missing or contains no readings.");
    return null;
  }
}

// ---------- Derive slot from LocationName ----------
const locName = msg.payload?.LocationName;

// Not a location message (e.g., frWS heartbeat). Let it pass through unchanged.
if (!locName) return msg;

// IMPORTANT: use the map you set in init (FR_locationPointerSlot)
const nameToSlot = global.get("FR_locationPointerSlot") || {};
const slot = Number(nameToSlot[locName]);

msg.locationName = locName;
msg.slot = Number.isFinite(slot) ? slot : null;
msg.isEnabledLocation = !!msg.slot && msg.slot >= 1 && msg.slot <= 15;

// If you want to DROP disabled/unmapped locations, keep this line:
if (!msg.isEnabledLocation) return null;

// Safe key for downstream notifications/routing (without using msg.api)
msg.endpointKey = `loc${msg.slot}_frWS`;

return msg;
``

let currentTime = Date.now(); // Get the current time in milliseconds
const eventCodes = env.get("EVENT_CODES");

// Retrieve the current subscription status from the global variable
let systemStatus = global.get("System_Status") || {};
systemStatus.API_Status = systemStatus.API_Status || {};

// Use System_Status.API_Status as the working object
let apiStatus = systemStatus.API_Status;

let currentFaultCount = 0;
let updatedFaultCount = 0;

// Initialize API status
let status = {
    healthy: true,
    reason: eventCodes.API.HEALTHY, // Use event code for healthy state
    lastUpdated: currentTime,       // Record the current time
    restFaultCount: {},
    restFault: false
};

// Define the APIs this function supports
const validAPI = ["dspREST", "frREST"];

// Check if the msg.api is valid
if (validAPI.includes(msg.api)) {

    // Ensure apiStatus[msg.api] exists
    apiStatus[msg.api] = apiStatus[msg.api] || { restFaultCount: {}, restFault: false, lastUpdated: 0 };

    // Current fault count
    if (msg.endpoint in (apiStatus[msg.api].restFaultCount || {})) {
        currentFaultCount = apiStatus[msg.api].restFaultCount[msg.endpoint];
    }

    // Check if the status code is in the 2xx range AND not latched in restFault
    if (msg.statusCode >= 200 && msg.statusCode < 300 && !(apiStatus[msg.api]?.restFault || false)) {
        status.healthy = true;
        status.reason = eventCodes.API.HEALTHY;

        status.restFaultCount = apiStatus[msg.api]?.restFaultCount || {};
        status.restFaultCount[msg.endpoint] = 0;

        if ("restFault" in apiStatus[msg.api]) {
            status.restFault = apiStatus[msg.api].restFault;
        } else {
            status.restFault = false;
        }

    } else {
        status.healthy = false;
        status.reason = eventCodes.API.HTTP_CLIENT_ERROR;

        // Keep previous lastUpdated on error
        status.lastUpdated = apiStatus[msg.api]?.lastUpdated || 0;

        status.restFaultCount = apiStatus[msg.api]?.restFaultCount || {};

        if (msg.statusCode >= 200 && msg.statusCode < 300) {
            status.restFaultCount[msg.endpoint] = 0;
        } else {
            status.restFaultCount[msg.endpoint] = (status.restFaultCount[msg.endpoint] || 0) + 1;
        }

        if ("restFault" in apiStatus[msg.api]) {
            status.restFault = apiStatus[msg.api].restFault;
        } else {
            status.restFault = true;
        }
    }

    // Update the status object
    apiStatus[msg.api] = status;

    // Persist to System_Status
    systemStatus.API_Status = apiStatus;
    global.set("System_Status", systemStatus);

    updatedFaultCount = status.restFaultCount[msg.endpoint];

    // Return the apiStatus for use in system health considerations
    if (status.healthy) {
        msg = {
            topic: msg.api.toString(),
            reset: true,
            payload: { apiStatus: apiStatus },
            lastFaultCount: currentFaultCount,
            currentFaultCount: updatedFaultCount,
            statusCode: msg.statusCode,
            endpoint: msg.endpoint
        };
    } else {
        msg = {
            topic: msg.api.toString(),
            payload: { apiStatus: apiStatus },
            lastFaultCount: currentFaultCount,
            currentFaultCount: updatedFaultCount,
            statusCode: msg.statusCode,
            endpoint: msg.endpoint
        };
    }

    return msg;
}

// If msg.api not valid, do nothing (or return null)
return null;

const now = Date.now();
const eventCodes = env.get("EVENT_CODES") || {};

const api = String(msg.api || "");
let previousWS = true;

// Pull globals
const locationStatus = global.get("locationStatus") || {};
const enabledList = global.get("FR_enabledLocationList") || [];
const slotToName = global.get("FR_slotToName") || null;

// System_Status.API_Status
let systemStatus = global.get("System_Status") || {};
systemStatus.API_Status = systemStatus.API_Status || {};
let apiStatus = systemStatus.API_Status;

// -------------------------------------------------------------------
// WebSocket health 
// -------------------------------------------------------------------
if (api === "frWS") {
  previousWS = !!apiStatus.frWS?.isHealthy;

  apiStatus.frWS = {
    isHealthy: true,
    reason: eventCodes.API?.HEALTHY ?? "HEALTHY",
    statusCode: apiStatus.frWS?.statusCode ?? null,
    lastUpdatedTimestamp: now,
    // preserve resetWS if handled elsewhere (e.g. watchdog)
    resetWS: apiStatus.frWS?.resetWS ?? false
  };

  // Persist ONLY to System_Status
  systemStatus.API_Status = apiStatus;
  global.set("System_Status", systemStatus);

  msg.previousWS = previousWS;
  msg.currentWS = true;
  msg.lastUpdate = "[00h 00m 00s]";
  return msg;
}

// -------------------------------------------------------------------
// 2) Per-location WebSocket updates
// -------------------------------------------------------------------
const m = api.match(/^loc(\d+)_frWS$/);
if (!m) {
  // Not a WebSocket update we care about
  return msg;
}

const slot = Number(m[1]);

// Resolve location name from slot
let locationName = null;

if (slotToName && slotToName[slot]) {
  locationName = slotToName[slot];
} else {
  // Fallback: enabledList indexing (slot 1 -> enabledList[0])
  locationName = enabledList[slot - 1];
}

if (!locationName) {
  node.warn(`Update_subscriptions: No location name found for slot ${slot} (${api}).`);
  return null;
}

// Ensure location exists
if (!locationStatus[locationName]) {
  node.warn(`Update_subscriptions: locationStatus missing for ${locationName}. Init may not have run.`);
  return null;
}

// Previous state for change detection
previousWS = !!locationStatus[locationName].apiStatus?.isHealthy;

// Update per-location WebSocket status
locationStatus[locationName].apiStatus = locationStatus[locationName].apiStatus || {};
locationStatus[locationName].apiStatus.isHealthy = true;
locationStatus[locationName].apiStatus.reason = eventCodes.API?.HEALTHY ?? "HEALTHY";
locationStatus[locationName].apiStatus.lastUpdatedTimestamp = now;

// Preserve resetWS (managed elsewhere)
locationStatus[locationName].apiStatus.resetWS =
  locationStatus[locationName].apiStatus.resetWS ?? false;

global.set("locationStatus", locationStatus);

// Build downstream message
msg.api = api;                    // e.g. "loc12_frWS"
msg.locationSlot = slot;
msg.locationName = locationName;
msg.previousWS = previousWS;
msg.currentWS = true;
msg.lastUpdate = "[00h 00m 00s]";

return msg;

const eventCodes = env.get("EVENT_CODES") || {}; // expects eventCodes.API.HEALTHY / UNHEALTHY
const apiHeartbeatThreshold = Number(env.get("API_DISCONNECT_TIMEOUT") || 5000);         // REST timeout
const apiWSHeartbeatThreshold = Number(env.get("FR_API_WS_DISCONNECT_TIMER") || 5000);  // WS timeout
const apiWSBeginResetThreshold = Number(env.get("FR_API_WS_RESET_TIMER") || 10000);     // WS reset threshold

// recovery delay (seconds)
const recoveryDelayS = Number(env.get("ALM_RECOVERY_DELAY") || 30);
const recoveryDelayMs = recoveryDelayS * 1000;

// startup alarm mask (seconds)
const initMaskS = Number(env.get("ALM_INIT_MASK_SECONDS") || 300);
const initMaskMs = initMaskS * 1000;

const now = Date.now();

// -------- formatting --------
function formatAge(ms) {
  const hours = Math.floor(ms / 3600000);
  const minutes = Math.floor((ms - (hours * 3600000)) / 60000);
  const seconds = Math.floor((ms - (hours * 3600000) - (minutes * 60000)) / 1000);
  return "[".concat(
    hours.toString().padStart(2, "0"), "h ",
    minutes.toString().padStart(2, "0"), "m ",
    seconds.toString().padStart(2, "0"), "s]"
  );
}

// event codes
const EC_HEALTHY = eventCodes.API?.HEALTHY ?? "HEALTHY";
const EC_UNHEALTHY = eventCodes.API?.UNHEALTHY ?? "UNHEALTHY";

// -------- pull globals --------
let systemStatus = global.get("System_Status") || {};
systemStatus.API_Status = systemStatus.API_Status || {};
let apiStatus = systemStatus.API_Status;

let locationStatus = global.get("locationStatus") || {};
const enabledList = global.get("FR_enabledLocationList") || []; // slot 1..15 -> location name

// -------- overall WS + REST age calculations (using lastUpdatedTimestamp) --------
const frWS_last = apiStatus.frWS?.lastUpdatedTimestamp || 0;
const frREST_last = apiStatus.frREST?.lastUpdatedTimestamp || 0;

const frWS_age = now - frWS_last;
const frREST_age = now - frREST_last;

// Build overall WS status
const previousfrWS = !!apiStatus.frWS?.isHealthy;
const statusWS = {
  isHealthy: frWS_age <= apiWSHeartbeatThreshold,
  reason: frWS_age > apiWSHeartbeatThreshold ? EC_UNHEALTHY : EC_HEALTHY,
  lastUpdatedTimestamp: frWS_last,
  resetWS: frWS_age >= apiWSBeginResetThreshold
};

// Build overall REST status (preserve restFault fields)
const previousfrREST = !!apiStatus.frREST?.isHealthy;
const statusREST = {
  isHealthy: frREST_age <= apiHeartbeatThreshold,
  reason: frREST_age > apiHeartbeatThreshold ? EC_UNHEALTHY : EC_HEALTHY,
  lastUpdatedTimestamp: frREST_last,
  restFault: apiStatus.frREST?.restFault ?? false,
  restFaultCount: apiStatus.frREST?.restFaultCount ?? {}
};

// Persist system endpoints back to apiStatus
apiStatus.frWS = statusWS;
apiStatus.frREST = statusREST;

// -------- per-location WS checks derived from enable list (slots 1..15) --------
const locCount = 15;
const loc = {}; // loc[i] = { previousHealthy, currentHealthy, lastUpdateStr }

let anyLocUnhealthy = false;

for (let slot = 1; slot <= locCount; slot++) {
  const locationName = enabledList[slot - 1];

  // If no enabled location for this slot, then n/a
  if (!locationName) {
    loc[slot] = {
      previousHealthy: false,
      currentHealthy: true,
      lastUpdateStr: "[--h --m --s]"
    };
    continue;
  }

  // Ensure location exists
  if (!locationStatus[locationName]) {
    loc[slot] = {
      previousHealthy: false,
      currentHealthy: false,
      lastUpdateStr: "[--h --m --s]"
    };
    anyLocUnhealthy = true;
    continue;
  }

  const prevHealthy = !!locationStatus[locationName].apiStatus?.isHealthy;

  const last = locationStatus[locationName].apiStatus?.lastUpdatedTimestamp || 0;
  const ageMs = now - last;
  const healthy = ageMs <= apiWSHeartbeatThreshold;

  // Update locationStatus API health
  locationStatus[locationName].apiStatus = locationStatus[locationName].apiStatus || {};
  locationStatus[locationName].apiStatus.isHealthy = healthy;
  locationStatus[locationName].apiStatus.reason = healthy ? EC_HEALTHY : EC_UNHEALTHY;
  locationStatus[locationName].apiStatus.resetWS = ageMs >= apiWSBeginResetThreshold;

  loc[slot] = {
    previousHealthy: prevHealthy,
    currentHealthy: healthy,
    lastUpdateStr: formatAge(ageMs)
  };

  if (!healthy) anyLocUnhealthy = true;
}

// Persist updated globals
systemStatus.API_Status = apiStatus;
global.set("System_Status", systemStatus);
global.set("locationStatus", locationStatus);

// -------- overall unhealthy decision --------
const overallUnhealthy = (!statusWS.isHealthy || !statusREST.isHealthy || anyLocUnhealthy);

// -------- output message --------
let outMsg = {
  payload: {
    system: "FrontRunner API",
    frWS: statusWS,
    frREST: statusREST,
    anyLocUnhealthy
  },
  topic: "fr",

  previousfrWS,
  currentfrWS: statusWS.isHealthy,
  lastfrWSUpdate: formatAge(frWS_age),

  previousfrREST,
  currentfrREST: statusREST.isHealthy,
  lastfrRESTUpdate: formatAge(frREST_age)
};

// Slot fields for notifications/dashboard
for (let i = 1; i <= locCount; i++) {
  outMsg[`previousfrWSLoc${i}`] = loc[i]?.previousHealthy ?? false;
  outMsg[`currentfrWSLoc${i}`] = loc[i]?.currentHealthy ?? false;
  outMsg[`lastfrWSLoc${i}Update`] = loc[i]?.lastUpdateStr ?? "[--h --m --s]";
}

// Alarm suppression + recovery debounce event monitoring
// -------------------------------------------------------------------

// Startup mask timestamp 
let maskUntil = global.get("INIT_ALM_MASK");
if (!maskUntil) {
  // fallback if INIT hasn't been set 
  maskUntil = now + initMaskMs;
  global.set("INIT_ALM_MASK", maskUntil);
}

const inStartupMask = now < maskUntil;

// Track alarm state in node context
let alarmActive = context.get("alarmActive") || false;         
let recoverySince = context.get("recoverySince") || 0;       

// Default flags
outMsg.raiseAlarm = false;     // send fault email
outMsg.clearAlarm = false;     // send recovery email
outMsg.suppressAlarms = inStartupMask;

// Keep compatibility from legacy
outMsg.wsAlarm = true;         // “message for ws alarm logic”
outMsg.reset = false;          // “clear alarm” pulse- requested when resetting)

// 1) If unhealthy: enter/maintain alarm immediately (but suppress notifications to prevent nuissance email notifications)
if (overallUnhealthy) {
  recoverySince = 0; // reset recovery timer
  context.set("recoverySince", 0);

  // Raise alarm on transition Ofrom healthy to FLT
  if (!alarmActive) {
    alarmActive = true;
    context.set("alarmActive", true);

    if (!inStartupMask) {
      outMsg.raiseAlarm = true;
    }
  }

  node.status({
    fill: "red",
    shape: "dot",
    text: inStartupMask
      ? `FrontRunner API: ${EC_UNHEALTHY} (muted)`
      : `FrontRunner API: ${EC_UNHEALTHY}`
  });

  return outMsg;
}

// 2) If healthy: if we were in alarm, require continuous healthy for recoveryDelay before clearing
if (alarmActive) {
  if (!recoverySince) {
    recoverySince = now;
    context.set("recoverySince", recoverySince);
  }

  const healthyForMs = now - recoverySince;
  const remainingMs = Math.max(0, recoveryDelayMs - healthyForMs);
  const remainingS = Math.ceil(remainingMs / 1000);

  outMsg.recoveryRemainingS = remainingS;

  // Not yet stable long enough -> still consider alarm active (no clear, no spam)
  if (healthyForMs < recoveryDelayMs) {
    node.status({
      fill: "yellow",
      shape: "dot",
      text: inStartupMask
        ? `Healthy, clear in ${remainingS}s (muted)`
        : `Healthy, clear in ${remainingS}s`
    });

    return outMsg;
  }

  // Stable long enough -> clear alarm (edge-triggered) unless masked
  alarmActive = false;
  context.set("alarmActive", false);
  context.set("recoverySince", 0);

  if (!inStartupMask) {
    outMsg.clearAlarm = true;
    outMsg.reset = true;  // keep your existing "clear" pulse semantics
  }

  node.status({
    fill: "green",
    shape: "dot",
    text: inStartupMask
      ? `FrontRunner API: ${EC_HEALTHY} (muted)`
      : `FrontRunner API: ${EC_HEALTHY}`
  });

  return outMsg;
}

// 3) Healthy and not in alarm: normal state
context.set("recoverySince", 0);

node.status({
  fill: "green",
  shape: "dot",
  text: inStartupMask
    ? `FrontRunner API: ${EC_HEALTHY} (muted)`
    : `FrontRunner API: ${EC_HEALTHY}`
});

return outMsg;

