// INIT: Build enabled-only status objects from FR_WS_LOCATIONS
const locations = env.get("FR_WS_LOCATIONS");

// Lists + maps for slot routing (enabled-only)
const enabledList = [];
const nameToSlot = {};
const slotToName = {};

// Status objects
const locationStatus = {};
const crushers = {};
const waterstands = {};

if (!Array.isArray(locations)) {
    node.error("FR_WS_LOCATIONS env var is not an array. Check it is valid JSON/typed env config.", msg);
    node.status({ fill: "red", shape: "dot", text: "FR_WS_LOCATIONS not array" });
    return null;
}

// interpret Enable/enable as boolean
function isEnabled(loc) {
    const enRaw = (loc?.Enable ?? loc?.enable);
    return (enRaw === true) || (String(enRaw || "").toUpperCase() === "TRUE");
}

// normalize asset type
function normType(t) {
    return String(t || "").trim().toUpperCase();
}

// Build enabled-only structures
for (const loc of locations) {
    const name = loc?.name;
    if (!name) continue;

    // Only include enabled assets
    if (!isEnabled(loc)) continue;

    const assetType = normType(loc?.AssetType);

    // --- active locationStatus info defined from env var ---
    locationStatus[name] = {
        meta: { assetType, name },
        plcStatus: {
            isHealthy: false,
            reason: null,
            currentHeartbeat: null,
            previousHeartbeat: null,
            lastUpdatedTimestamp: 0
        },
        apiStatus: {
            isHealthy: false,
            reason: null,
            statusCode: null,
            lastUpdatedTimestamp: 0,
            resetWS: false
        }
    };

    // --- define location pointers for active units ---
    enabledList.push(name);
    if (enabledList.length <= 15) {
        const slot = enabledList.length;   // 1..15
        nameToSlot[name] = slot;
        slotToName[slot] = name;
    }

    // --- crusher definitions active ---
    if (assetType === "CRUSHER") {
        crushers[name] = {
            meta: { assetType, name },
            status: {
                isHealthy: false,
                reason: null,
                lastUpdatedTimestamp: 0
            }
        };
    }

    // --- defne enabled water stands ---
    if (assetType === "WATER_STAND" || assetType === "WATERSTAND") {
        waterstands[name] = {
            meta: { assetType, name },

            // Align with AWS function structure
            dt: {
                AWT: {
                    Name: "",
                    Mode: "",
                    Speed: null,
                    WaterLevel: null,
                    AtSpot: null,
                    CoordinateX: null,
                    CoordinateY: null,
                    MotionStopOwnerList: [],
                    isLockedByClient: null
                },
                AWS: {
                    Skid: "",
                    Ready: null
                },
                lastUpdatedFromAPI: 0
            }
        };
    }

}

// Persist globals for locations
global.set("locationStatus", locationStatus);
global.set("Crushers", crushers);
global.set("WaterStands", waterstands);

global.set("FR_enabledLocationList", enabledList);
global.set("FR_locationPointerSlot", nameToSlot);
global.set("FR_slotToName", slotToName);

// System_Status migration 
let systemStatus = global.get("System_Status") || {};

// Pull existing apiStatus (source today)
let apiStatus = global.get("apiStatus");

// Seed defaults if missing
if (!apiStatus || typeof apiStatus !== "object") {
    apiStatus = {
        frWS: {
            isHealthy: false,
            reason: 1001,
            lastUpdatedTimestamp: 0,
            resetWS: true
        },
        frREST: {
            isHealthy: false,
            reason: 1001,
            lastUpdatedTimestamp: 0,
            restFault: false,
            restFaultCount: {}
        }
    };
}

// Replace API_Status with your structure (Temp)
systemStatus.API_Status = apiStatus;

// PLC object
systemStatus.FMS_PLC_Status = systemStatus.FMS_PLC_Status || { isHealthy: false } || { reason: null } || { lastUpdatedTimeStamp: 0 };


// Persist
global.set("System_Status", systemStatus);


// --- Alarm startup mask (prevents alarm spam after Node-RED restart) ---
const maskSeconds = Number(env.get("ALM_INIT_MASK_SECONDS") || 120); // 2 minutes default
const now = Date.now();

global.set("INIT_ALM_MASK", now + (maskSeconds * 1000));

// Operator feedback
node.status({
    fill: "green",
    shape: "dot",
    text: `Act. Locations: ${enabledList.length} ( Crushers: ${Object.keys(crushers).length} | WaterStands: ${Object.keys(waterstands).length} )`
});

 return null;
``

