//The Modbus-Flex-Getter Node is expecting msg.payload.fc, unitid, address and quatity to work properly as defined below 
// each Modbus Read is limited by the size of 125 registers per request, thus, it is splitted into three to read data for 12 AWS
node.send({
    payload: { fc: 3, unitid: 1, address: 1000, quantity: 125 },
    topic: "block0"
});

node.send({
    payload: { fc: 3, unitid: 1, address: 1125, quantity: 125 },
    topic: "block125"
});

node.send({
    payload: { fc: 3, unitid: 1, address: 1250, quantity: 125 },
    topic: "block250"
});

return null;

// Purpose: Summarise a flow's node status messages into one flow health value.
// Input:   msg from a Node-RED Status node, with msg.status and msg.source.
// Output:  msg.payload = { timestamp, status }
